INSERT INTO saas.content_articles (slug,title,excerpt,body_markdown,seo_title,seo_description,keywords,image_url,image_source,status,source_workflow) VALUES
('como-encontrar-oportunidades-secopp-ii-para-tu-empresa','Cómo encontrar oportunidades de contratación pública en SECOP II para tu empresa','Una guía práctica para priorizar oportunidades que corresponden a las capacidades de tu empresa.','## Empieza por tu capacidad real\n\nLa búsqueda funciona mejor cuando parte de productos y servicios, códigos UNSPSC, experiencia, cobertura geográfica, modalidades y capacidad financiera que tu empresa puede demostrar.\n\n## Lee el proceso completo\n\nRevisa descripción, entidad, presupuesto, publicación, cronograma y documentos. Si SECOP II no informa un cierre, consulta el cronograma y sus adendas oficiales.\n\n## Separa afinidad de cumplimiento\n\nQue una oportunidad se parezca a tu actividad no significa que cumplas todos los requisitos. Una priorización responsable muestra coincidencias, faltantes y documentos por revisar.\n\n## Convierte la búsqueda en un proceso comercial\n\nRegistra por qué una oportunidad es relevante, quién debe revisarla y qué soporte falta. CernoIA reúne procesos, afinidad, requisitos y documentos para decidir con contexto.','Oportunidades SECOP II: guía para empresas | CernoIA','Aprende a encontrar y priorizar oportunidades de contratación pública en SECOP II según las capacidades reales de tu empresa.','["SECOP II","contratación pública","oportunidades para empresas","UNSPSC"]'::jsonb,'https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?auto=format&fit=crop&w=1400&q=78','https://unsplash.com/photos/1454165804606-c3d57bc86b40','published','seed-content'),
('documentos-requisitos-contratacion-publica-checklist','Documentos y requisitos para participar en contratación pública: checklist empresarial','Verifica vigencia y evidencia antes de preparar una oferta.','## El documento depende del proceso\n\nCada entidad define requisitos, formatos y fechas en los documentos del proceso. Identifica primero qué se exige y en qué etapa.\n\n## Checklist de preparación\n\n- Certificado de existencia y representación legal vigente, cuando corresponda.\n- Registro Único Tributario y datos consistentes.\n- Certificados de experiencia relacionados.\n- Información financiera y soportes solicitados.\n- Pólizas, declaraciones, formatos y anexos del contratante.\n\n## Controla vigencia y trazabilidad\n\nCargar un archivo no equivale a tenerlo validado. Registra expedición, vencimiento, extracción y revisión. Conserva el original y relaciónalo con el requisito que respalda.\n\n## Revisa los anexos oficiales\n\nLos formatos deben conservarse y diligenciarse con datos comprobados. El autollenado responsable identifica campos pendientes y exige revisión humana antes de firmar.','Checklist de documentos para contratación pública | CernoIA','Conoce un checklist práctico de documentos y requisitos para preparar ofertas de contratación pública.','["documentos contratación pública","requisitos SECOP II","ofertas públicas","checklist empresarial"]'::jsonb,'https://images.unsplash.com/photo-1554224155-6726b3ff858f?auto=format&fit=crop&w=1400&q=78','https://unsplash.com/photos/1554224155-6726b3ff858f','published','seed-content'),
('como-mejorar-afinidad-procesos-contratacion-publica','Cómo mejorar la afinidad de tu empresa con procesos de contratación pública','La afinidad mejora cuando el perfil empresarial refleja con precisión lo que haces y la evidencia disponible.','## La afinidad no es una promesa de adjudicación\n\nSirve para ordenar la revisión; no es una probabilidad de ganar ni reemplaza la lectura jurídica y técnica.\n\n## Completa tu perfil con precisión\n\nRegistra productos, códigos UNSPSC, departamentos, modalidades, tipos de contrato y rangos de presupuesto realistas. No agregues capacidades que no puedas demostrar.\n\n## Usa documentos como evidencia\n\nLos certificados ayudan a revisar requisitos, pero deben estar vigentes, legibles y asociados a la empresa correcta. CernoIA muestra soportes faltantes o pendientes para cargarlos y solicitar un nuevo análisis.\n\n## Decide con una explicación\n\nUna buena oportunidad combina objeto compatible, cronograma posible y requisitos con una ruta de verificación.','Afinidad en contratación pública: cómo mejorarla | CernoIA','Mejora la afinidad de tu empresa con procesos de contratación pública completando capacidades y evidencia documental.','["afinidad contratación pública","perfil empresarial","UNSPSC","SECOP II"]'::jsonb,'https://images.unsplash.com/photo-1556761175-b413da4baf72?auto=format&fit=crop&w=1400&q=78','https://unsplash.com/photos/1556761175-b413da4baf72','published','seed-content')
